  cudaMalloc(&d_result, num_rows * num_rows * sizeof(REAL));

  cudaMemcpy(d_ptrA, ptrA, (num_rows+1)*sizeof(int), cudaMemcpyHostToDevice);
  cudaMemcpy(d_indicesA, indicesA, nnzA*sizeof(int), cudaMemcpyHostToDevice);
